function writeFileSafe(filePath, content) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, content);
  console.log(`📄 Created: ${filePath}`);
}

function installProject(targetDir) {
  for (const [relPath, b64] of Object.entries(projectFiles)) {
    const fullPath = path.join(targetDir, relPath);
    const data = Buffer.from(b64, 'base64');
    writeFileSafe(fullPath, data);
  }
  console.log("✅ Project unpacked into", targetDir);

  try {
    console.log("> npm install");
    execSync("npm install", { stdio: "inherit", cwd: targetDir });
  } catch (err) {
    console.error("⚠️ npm install failed:", err.message);
  }
}

installProject(targetDir);
